#!/bin/sh
# Self-contained companion 1.0.8; registration revision 1.
set -eu
firefox_root=''
firefox_port=''
firefox_no_clients=''
while [ "$#" -gt 0 ]; do
  case "$1" in
    --root) [ "$#" -ge 2 ] || { echo '--root needs a directory.' >&2; exit 1; }; firefox_root=$2; shift 2 ;;
    --port) [ "$#" -ge 2 ] || { echo '--port needs a number.' >&2; exit 1; }; firefox_port=$2; shift 2 ;;
    --no-register-clients) firefox_no_clients='--no-register-clients'; shift ;;
    --help) echo 'sh register.sh [--root ABSOLUTE_DIRECTORY] [--port 38477] [--no-register-clients]'; echo 'Installs/updates a local Node.js MCP server and native host, then registers them. About 22 MB plus Node.js; requires Node.js 22+ and npm.'; echo 'Existing server/setup source files in the selected directory may be replaced.'; exit 0 ;;
    *) echo "Unknown option: $1" >&2; exit 1 ;;
  esac
done
echo 'This script installs/updates a local Node.js MCP server and native host, then registers them.'
echo 'Server and npm dependencies: about 22 MB; Node.js is additional. Existing server/setup source files may be replaced.'
command -v node >/dev/null 2>&1 || { echo 'Install Node.js 22+ and npm, then run this script again.' >&2; exit 1; }
node -e 'if (Number(process.versions.node.split(".")[0]) < 22) process.exit(1)' || { echo 'Node.js 22+ is required.' >&2; exit 1; }
case "$(uname -s)" in
  Darwin) firefox_default="$HOME/Library/Application Support/FirefoxCodexMCP"; firefox_manifest="$HOME/Library/Application Support/Mozilla/NativeMessagingHosts/de.codex.firefox_bridge.json" ;;
  Linux) firefox_default="$HOME/.local/share/firefox-codex-mcp"; firefox_manifest="$HOME/.mozilla/native-messaging-hosts/de.codex.firefox_bridge.json" ;;
  *) echo 'This script supports Linux and macOS.' >&2; exit 1 ;;
esac
firefox_installed=$(node -e 'const fs=require("node:fs"),p=require("node:path");try{const m=JSON.parse(fs.readFileSync(process.argv[1],"utf8"));if(m.name!=="de.codex.firefox_bridge"||m.type!=="stdio"||m.allowed_extensions.length!==1||m.allowed_extensions[0]!=="firefox-codex-mcp@local.invalid"||p.basename(m.path)!=="native-host.sh"||p.basename(p.dirname(m.path))!==".local")process.exit(0);process.stdout.write(p.dirname(p.dirname(m.path)))}catch{}' "$firefox_manifest")
if [ -n "$firefox_installed" ]; then
  firefox_default=$firefox_installed
  echo 'Default: directory of the existing registration (this may be a development/source directory).'
else
  echo 'Default: per-user application data directory for a new installation.'
fi
if [ -z "$firefox_root" ]; then
  [ -t 0 ] || { echo 'Supply --root ABSOLUTE_DIRECTORY for non-interactive setup.' >&2; exit 1; }
  printf 'Installation directory [%s]: ' "$firefox_default"
  read -r firefox_root
  if [ -z "$firefox_root" ]; then firefox_root=$firefox_default; fi
fi
case "$firefox_root" in /*) ;; *) echo '--root needs an absolute directory.' >&2; exit 1 ;; esac
firefox_root=$(node -e 'process.stdout.write(require("node:path").resolve(process.argv[1]))' "$firefox_root")
printf 'Selected installation directory: %s\n' "$firefox_root"
if [ -n "$firefox_installed" ]; then firefox_installed=$(node -e 'process.stdout.write(require("node:path").resolve(process.argv[1]))' "$firefox_installed"); fi
node --input-type=module - "$firefox_root" "$firefox_no_clients" "$firefox_port" <<'FIREFOX_COMPANION_JS'
import { createHash } from 'node:crypto';
import { lstat, mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import { gzipSync, gunzipSync } from 'node:zlib';

const PAYLOAD_SCHEMA = 1;
const companionFiles = [
  'package.json', 'package-lock.json', 'LICENSE.md', 'README.md', 'PROTOCOL.md',
  'install.ps1', 'uninstall.ps1', 'scripts/node-runtime.ps1', 'scripts/open-firefox-setup.ps1', 'scripts/finish-relocation.ps1',
  'scripts/setup.mjs', 'scripts/registration.mjs', 'scripts/install-companion.mjs',
  'scripts/companion-payload.mjs', 'scripts/client-config.mjs', 'scripts/configure-clients.mjs',
];
const digest = bytes => createHash('sha256').update(bytes).digest('hex');

function validatePayload(payload) {
  if (payload?.schemaVersion !== PAYLOAD_SCHEMA || typeof payload.version !== 'string' || !Array.isArray(payload.files) || payload.files.length > 200) throw new Error('Invalid companion payload.');
  const seen = new Set();
  for (const file of payload.files) {
    if (typeof file.path !== 'string' || !/^[a-zA-Z0-9][a-zA-Z0-9._/-]*$/.test(file.path) || file.path.split('/').some(part => !part || part === '.' || part === '..') || seen.has(file.path)) throw new Error('Invalid companion payload path.');
    seen.add(file.path);
    if (typeof file.data !== 'string' || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(file.data)) throw new Error('Invalid companion payload data.');
    const bytes = Buffer.from(file.data, 'base64');
    if (bytes.length > 4 * 1024 * 1024 || file.sha256 !== digest(bytes)) throw new Error('Companion payload checksum failed.');
  }
  for (const needed of ['package.json', 'package-lock.json', 'scripts/setup.mjs', 'scripts/install-companion.mjs', 'server/native-host.mjs']) {
    if (!seen.has(needed)) throw new Error('Incomplete companion payload: ' + needed);
  }
  return payload;
}

async function buildPayload(root) {
  const serverFiles = (await readdir(join(root, 'server'))).filter(name => name.endsWith('.mjs')).map(name => 'server/' + name);
  const files = await Promise.all([...companionFiles, ...serverFiles].sort().map(async path => {
    const bytes = await readFile(join(root, path));
    return { path, sha256: digest(bytes), data: bytes.toString('base64') };
  }));
  const { version } = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
  return validatePayload({ schemaVersion: PAYLOAD_SCHEMA, version, files });
}

function encodePayload(payload) {
  const bytes = gzipSync(Buffer.from(JSON.stringify(validatePayload(payload))), { level: 9 });
  return { base64: bytes.toString('base64'), sha256: digest(bytes) };
}

function decodePayload(base64, sha256) {
  const bytes = Buffer.from(base64, 'base64');
  if (digest(bytes) !== sha256) throw new Error('Companion archive checksum failed.');
  return validatePayload(JSON.parse(gunzipSync(bytes, { maxOutputLength: 16 * 1024 * 1024 }).toString('utf8')));
}

async function ordinaryPath(path, directory) {
  try {
    const info = await lstat(path);
    if (info.isSymbolicLink() || !(directory ? info.isDirectory() : info.isFile()) || (!directory && info.nlink !== 1)) throw new Error('Setup target is not an ordinary ' + (directory ? 'directory: ' : 'file: ') + path);
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
}

async function extractPayload(payload, root) {
  validatePayload(payload);
  if (!isAbsolute(root) || resolve(root) === dirname(resolve(root))) throw new Error('Choose an absolute installation directory, not a filesystem root.');
  root = resolve(root);
  // Check existing ancestors as well as children: no writes through symlinks.
  const ancestors = [];
  for (let parent = root; dirname(parent) !== parent; parent = dirname(parent)) ancestors.unshift(parent);
  for (const path of ancestors) await ordinaryPath(path, true);
  await mkdir(root, { recursive: true, mode: 0o700 });
  const previous = join(root, 'package.json');
  await ordinaryPath(previous, false);
  try {
    const installed = JSON.parse(await readFile(previous, 'utf8'));
    if (installed.name !== 'firefox-codex-mcp') throw new Error('Installation directory belongs to another application.');
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
  // Validate every destination before touching existing project files.
  for (const file of payload.files) {
    const target = resolve(root, file.path);
    if (relative(root, target).startsWith('..' + sep)) throw new Error('Payload path escaped installation directory.');
    const pieces = file.path.split('/');
    let parent = root;
    for (const part of pieces.slice(0, -1)) { parent = join(parent, part); await ordinaryPath(parent, true); }
    await ordinaryPath(target, false);
  }
  for (const file of payload.files) {
    const target = join(root, file.path);
    await mkdir(dirname(target), { recursive: true, mode: 0o700 });
    await writeFile(target, Buffer.from(file.data, 'base64'), { mode: 0o600 });
  }
  return root;
}

const payload = decodePayload('', '38d8a3f7965d54ef773178d5b02bf73e620438e119ff4092225b61ddcd6bb090');
const root = await extractPayload(payload, process.argv[2]);
const { pathToFileURL } = await import('node:url');
const { main } = await import(pathToFileURL(join(root, 'scripts/install-companion.mjs')).href);
const args = ['--root', root];
if (process.argv[3]) args.push(process.argv[3]);
if (process.argv[4]) args.push('--port', process.argv[4]);
process.exitCode = await main(args);
FIREFOX_COMPANION_JS
echo 'Return to the extension settings and choose Check again.'
